package org.sleepwell.app;
import android.app.Activity;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;
import java.util.*;import java.util.concurrent.*;
/** Local global search or a settings-only directory. Opening a result never starts an output. */
public final class SearchActivity extends Activity {
    public static final String EXTRA_MODE="searchMode",MODE_SETTINGS="settings";
    public static Intent settingsIntent(Activity owner){return RecordUi.intent(owner,SearchActivity.class).putExtra(EXTRA_MODE,MODE_SETTINGS);}
    private final ExecutorService reader=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private String query="",error="",category="";private int generation;private boolean loaded,settingsOnly;private List<SearchIndex.Entry> index=List.of();private LinearLayout results,filters;private TextView status;private EditText input;
    private final Runnable searchLater=this::search;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);settingsOnly=MODE_SETTINGS.equals(getIntent().getStringExtra(EXTRA_MODE));if(saved!=null){query=saved.getString("query","");settingsOnly=saved.getBoolean("settingsOnly",settingsOnly);category=saved.getString("category","");}if(query.length()>160)query=query.substring(0,160);if(!SearchSettings.category(category))category="";render();}
    @Override protected void onResume(){super.onResume();load();}
    private void load(){int request=++generation;loaded=false;status.setText(settingsOnly?"Opening settings…":"Opening local search…");reader.execute(()->{try{List<SearchIndex.Entry> snapshot=settingsOnly?SearchData.settings():SearchData.read(getApplicationContext());runOnUiThread(()->{if(isDestroyed()||request!=generation)return;index=snapshot;loaded=true;error="";search();});}catch(RuntimeException failed){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;error=settingsOnly?"Settings search could not open.":"Search could not open your saved data.";status.setText(error);results.removeAllViews();Design.button(results,"Try again",true,this::load);});}});}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,settingsOnly?"Search settings":"Search SleepWell",this::finish);Design.space(body,12);RecordUi.segments(body,new String[]{"Search everything","Settings only"},settingsOnly?1:0,n->{boolean next=n==1;if(next==settingsOnly)return;if(input!=null)query=input.getText().toString();settingsOnly=next;main.removeCallbacks(searchLater);render();load();});Design.space(body,12);input=new EditText(this);input.setSingleLine();input.setTextSize(16*Appearance.scale(this));input.setTypeface(Design.font(this,400));input.setTextColor(Design.INK);input.setHintTextColor(Design.MUTED);input.setHint(settingsOnly?"Try snoring, flashlight or backup":"Alarms, notes, tags or settings");input.setContentDescription(settingsOnly?"Search settings query":"Search query");input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(160)});input.setImeOptions(EditorInfo.IME_ACTION_SEARCH);input.setBackground(Design.shape(this,Design.SOFT,14));Design.pad(input,14,12);input.setText(query);body.addView(input,new LinearLayout.LayoutParams(-1,Design.dp(this,56)));input.setOnEditorActionListener((v,action,event)->{if(action!=EditorInfo.IME_ACTION_SEARCH)return false;search();return true;});input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();main.removeCallbacks(searchLater);main.postDelayed(searchLater,180);}public void afterTextChanged(Editable e){}});
        if(settingsOnly){Design.space(body,8);HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);filters=Design.row(this);scroll.addView(filters);body.addView(scroll,new LinearLayout.LayoutParams(-1,Design.dp(this,48)));renderFilters();}
        Design.space(body,12);status=Design.text(body,"",13,400,Design.MUTED);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);Design.space(body,12);results=Design.col(this);body.addView(results);}
    private void renderFilters(){if(filters==null)return;filters.removeAllViews();List<String> options=new ArrayList<>();options.add("");options.addAll(SearchSettings.CATEGORIES);for(String value:options){String name=value.isEmpty()?"All settings":value;View chip=RecordUi.chip(this,name,category.equals(value),()->{category=value;renderFilters();search();});chip.setContentDescription("Filter settings: "+name);LinearLayout.LayoutParams gap=new LinearLayout.LayoutParams(-2,Design.dp(this,48));gap.rightMargin=Design.dp(this,4);filters.addView(chip,gap);}}
    private void search(){if(!loaded||isDestroyed())return;int request=++generation;String searched=query,chosenCategory=category;List<SearchIndex.Entry> source=index;reader.execute(()->{List<SearchIndex.Entry> found=settingsOnly?SearchIndex.findSettings(source,searched,chosenCategory):SearchIndex.find(source,searched);runOnUiThread(()->{if(isDestroyed()||request!=generation)return;results.removeAllViews();boolean blank=SearchIndex.normalize(searched).isEmpty();if(blank&&!settingsOnly){status.setText("Search your alarms, sleep records and settings.");return;}String count=found.size()+(found.size()==100?" results · first 100 shown":found.size()==1?" result":" results");status.setText(found.isEmpty()?settingsOnly?"No matching settings · try another term or category":"No matching results":settingsOnly?(chosenCategory.isEmpty()?"All settings":chosenCategory)+" · "+count:count);for(SearchIndex.Entry entry:found){LinearLayout row=PlanActivity.detail(results,entry.kind==SearchIndex.Kind.ALARM?"alarm":entry.kind==SearchIndex.Kind.RECORD?"report":"settings",entry.title,entry.subtitle,null,()->open(entry));row.setMinimumHeight(Design.dp(this,64));row.setContentDescription(entry.title+". "+entry.subtitle.replace('\n',' ')+". Open");Design.line(results);}});});}
    private void open(SearchIndex.Entry entry){if(isDestroyed()||isFinishing()||!hasWindowFocus())return;if(entry.kind==SearchIndex.Kind.SETTING){try{startActivity(SearchSettings.intent(this,entry.id));}catch(ActivityNotFoundException|IllegalArgumentException unavailable){status.setText("This setting could not be opened. Refresh the search.");}return;}if(entry.kind==SearchIndex.Kind.RECORD){startActivity(RecordUi.intent(this,RecordReportActivity.class).putExtra("record",entry.id));return;}int request=++generation;reader.execute(()->{String saved=null;try(Store store=Records.open(getApplicationContext())){Alarm alarm=store.alarm(Math.toIntExact(entry.id));if(alarm!=null)saved=alarm.json().toString();}catch(RuntimeException ignored){}String draft=saved;runOnUiThread(()->{if(isDestroyed()||request!=generation)return;if(draft==null){status.setText("This alarm changed. Refresh the search.");load();}else startActivity(RecordUi.intent(this,AlarmEditorActivity.class).putExtra("alarm",draft));});});}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("query",query);state.putBoolean("settingsOnly",settingsOnly);state.putString("category",category);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){generation++;main.removeCallbacksAndMessages(null);reader.shutdownNow();super.onDestroy();}
    boolean awaitReaders(long millis)throws InterruptedException{return reader.awaitTermination(millis,TimeUnit.MILLISECONDS);}
}
